from django.core.management.base import BaseCommand
from core.models import ContentBlock, SiteSettings
from pages.models import Page, FAQ

class Command(BaseCommand):
    help = 'Create editable initial Russian content without overwriting CMS edits or inventing translations.'
    def handle(self, *args, **kwargs):
        blocks = [('benefit','Автомобиль под задачу','От городского седана до большого внедорожника. Выберите класс и модель в каталоге.'), ('benefit','Быстрое оформление','Выберите автомобиль, оставьте заявку и согласуйте детали с менеджером.'), ('benefit','Доставка автомобиля','Согласуйте с менеджером получение автомобиля в удобной точке вашего города.'), ('benefit','Длительная аренда выгоднее','На страницах автомобилей опубликованы скидки по срокам аренды.'), ('step','Выберите автомобиль','Посмотрите фотографии, стоимость и доступные города.'), ('step','Оставьте заявку','Укажите телефон и желаемые даты аренды.'), ('step','Согласуйте детали','Менеджер подтвердит наличие, стоимость и условия.'), ('step','Получите ключи','Получите автомобиль и подпишите договор аренды.'), ('condition','Документы','Для оформления нужны водительское удостоверение и удостоверение личности.'), ('condition','Личная аренда','Автомобили не сдаются для работы в такси и доставки.'), ('condition','Депозит и ограничения','Возраст, стаж, депозит, пробег и территорию поездок уточните у менеджера до подписания договора.'), ('condition','Получение и возврат','Согласуйте время и место получения и возврата автомобиля с менеджером.')]
        for order, (kind, title, text) in enumerate(blocks): ContentBlock.objects.get_or_create(kind=kind, title=title, defaults={'text': text, 'sort_order': order})
        pages = [
            ('about','О Legion Auto Rent','Автомобиль под ваши планы.','<h2>Прокат автомобилей без водителя</h2><p>Legion Auto Rent предлагает автомобили разных классов в Астане, Костанае, Усть-Каменогорске и Павлодаре. В каталоге можно посмотреть реальные фотографии, стоимость аренды и скидки на длительные поездки.</p><h2>Выбор и оформление</h2><p>Выберите автомобиль и оставьте заявку. Менеджер уточнит наличие на выбранные даты, стоимость, документы и условия договора. Получение автомобиля и доставку можно согласовать заранее.</p><p><a href="/cars/">Выбрать автомобиль</a> · <a href="/contacts/">Связаться с нами</a></p>'),
            ('rental-conditions','Условия аренды','Всё важное до начала поездки.','<h2>Документы</h2><p>Для аренды нужны водительское удостоверение и удостоверение личности.</p><h2>Возраст, стаж и депозит</h2><p>Требования к возрасту и стажу, размер депозита и способ оплаты согласуйте с менеджером для выбранного автомобиля до оформления договора.</p><h2>Сроки и стоимость</h2><p>Базовая стоимость и скидки опубликованы на странице каждого автомобиля. Итоговая цена зависит от согласованного срока и условий. Границы скидочных периодов подтвердит менеджер.</p><h2>Получение и возврат</h2><p>Время, место получения и возврата согласовываются заранее. Возможность и стоимость доставки уточните при оформлении заявки.</p><h2>Ограничения</h2><p>Автомобили не сдаются для работы в такси и доставки. Пробег, территорию поездок, дополнительные услуги и остальные условия уточните до подписания договора.</p>'),
            ('contacts','Контакты','Legion Auto Rent в вашем городе.','<p>Выберите город и свяжитесь с нами по телефону или WhatsApp. Менеджер поможет с выбором автомобиля и условиями аренды.</p>'),
            ('privacy','Политика конфиденциальности','','<h2>Обработка заявки</h2><p>Отправляя заявку, вы предоставляете Legion Auto Rent имя, телефон, выбранный автомобиль, город, даты и комментарий для ответа на ваш запрос и согласования аренды.</p><p>Также сохраняются страница обращения и рекламные параметры источника. Форма не запрашивает платёжные данные или документы.</p><p>По вопросам обработки и удаления данных обратитесь по телефону, указанному в контактах сайта.</p>'),
            ('consent','Согласие на обработку данных','','<p>Я согласен на обработку имени, телефона, дат аренды и комментария компанией Legion Auto Rent для ответа на мою заявку.</p>')]
        for slug, title, intro, body in pages:
            legal = slug in ('privacy','consent')
            Page.objects.get_or_create(slug=slug, defaults={'title': title, 'path': f'/{slug}/', 'intro': intro, 'body': body, 'seo_title': title + ' | Legion Auto Rent', 'seo_h1': title, 'seo_description': intro or title + ' — информация Legion Auto Rent.', 'robots': 'noindex,follow' if legal else 'index,follow', 'show_in_footer': legal})
        for order, (question, answer) in enumerate([('Как забронировать автомобиль?','Выберите автомобиль и отправьте заявку с телефоном и желаемыми датами. Менеджер свяжется с вами, уточнит наличие и условия. Заявка сама по себе не подтверждает бронирование.'), ('Какие документы нужны для аренды?','Водительское удостоверение и удостоверение личности. Возраст, стаж и другие требования уточните у менеджера для выбранного автомобиля.'), ('Можно ли взять автомобиль для работы в такси?','Нет. Автомобили Legion Auto Rent не сдаются для работы в такси и доставки.'), ('Есть ли скидки на длительную аренду?','На страницах автомобилей опубликованы скидки по срокам аренды. Итоговую стоимость и границы периодов подтвердит менеджер.'), ('Можно ли получить автомобиль с доставкой?','Место получения и возможность доставки согласуйте с менеджером при оформлении заявки.')]):
            FAQ.objects.get_or_create(question=question, defaults={'answer': answer, 'sort_order': order})
        self.stdout.write('Initial CMS content created; existing content preserved. Legal drafts require owner approval.')
